#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

SCOPE="trythursday"
PLACEHOLDER_NAME="@${SCOPE}/bootstrap"
PLACEHOLDER_VERSION="0.0.1"

banner "Claim the @${SCOPE} scope on npm"

# On npm, a scope is owned by whoever first creates a user or org with that
# name and publishes under it. Creating the org reserves the name; the first
# publish proves it. Doing this early is cheap; doing it late risks the name.

# ── Stage 1: npm identity ─────────────────────────────────────────────────
stage "npm: who are you logged in as"
if command -v npm >/dev/null 2>&1; then
  if NPM_USERNAME_CURRENT="$(npm whoami 2>/dev/null)"; then
    say "Already logged in to npm as ${BOLD}${NPM_USERNAME_CURRENT}${RESET}."
    ask NPM_USERNAME "Enter to keep this account, or type another username:"
    [[ -z "$NPM_USERNAME" ]] && NPM_USERNAME="$NPM_USERNAME_CURRENT"
  else
    say "Not logged in to npm."
    step "Run the login when prompted; it opens a browser to authenticate."
    pause "Press Enter to start npm login"
    npm login
    NPM_USERNAME="$(npm whoami 2>/dev/null || true)"
  fi
else
  warn "npm not found on PATH; install Node.js first, then re-run this wizard."
  exit 1
fi
[[ -n "$NPM_USERNAME" ]] && write_env NPM_USERNAME "$NPM_USERNAME"

# ── Stage 2: create the org ───────────────────────────────────────────────
stage "npm: create the ${SCOPE} org"
say "An npm scope is owned by the user or org of the same name. Creating the"
say "org ${BOLD}${SCOPE}${RESET} reserves it. The free plan allows unlimited public packages."
open_url "https://www.npmjs.com/org/create"
step "Sign in if asked, then set the org name to: ${BOLD}${SCOPE}${RESET}"
step "Choose the ${BOLD}unlimited public packages${RESET} (free) plan."
step "Click Create. The org page becomes npmjs.com/org/${SCOPE}."
if confirm "Did the org get created (you can see it at npmjs.com/org/${SCOPE})?"; then
  note "Scope name is now reserved by your account."
else
  warn "If the name was taken, stop here and pick a different scope with the"
  warn "team before anything publishes. Re-run this wizard once decided."
  pause "Press Enter to continue anyway (you can verify in the last stage)"
fi

# ── Stage 3: prove it with a placeholder publish ──────────────────────────
stage "npm: publish the placeholder"
say "The claim isn't proven until a package exists under the scope. A tiny"
say "placeholder, ${BOLD}${PLACEHOLDER_NAME}${RESET}, does that without touching the real packages."
PLACEHOLDER_DIR="$(mktemp -d)"
trap 'rm -rf "$PLACEHOLDER_DIR"' EXIT
mkdir -p "$PLACEHOLDER_DIR"
cat > "$PLACEHOLDER_DIR/package.json" <<EOF
{
  "name": "${PLACEHOLDER_NAME}",
  "version": "${PLACEHOLDER_VERSION}",
  "description": "Placeholder that claims the @${SCOPE} scope for the Thursday project (trythursday.org). Not for use.",
  "license": "UNLICENSED",
  "private": false
}
EOF
if confirm "Publish ${PLACEHOLDER_NAME}@${PLACEHOLDER_VERSION} now?"; then
  if ( cd "$PLACEHOLDER_DIR" && npm publish --access public ); then
    printf '  %s✓ published%s %s@%s\n' "$GREEN" "$RESET" "$PLACEHOLDER_NAME" "$PLACEHOLDER_VERSION"
  else
    warn "publish failed. Check the error: if it says the scope is taken or"
    warn "forbidden, the org was not created under this account; go back a stage."
  fi
else
  SKIPPED+=("placeholder publish (run it later from any dir with that package.json)")
  warn "Skipped. The scope is reserved but unproven until something publishes."
fi

# ── Stage 4: CI token ─────────────────────────────────────────────────────
stage "npm: CI access token"
say "The publishing workflow will need a token with write access to the scope."
say "A granular token limited to packages in ${BOLD}${SCOPE}${RESET} keeps the blast radius small."
open_url "https://www.npmjs.com/settings/~/tokens/granular-access-tokens/new"
step "Name it: ${BOLD}thursday-ci${RESET}"
step "Under Packages and scopes, grant read and write only to packages in the ${SCOPE} scope."
step "Set the shortest expiry you are willing to live with, then Generate Token."
step "Copy the token (starts npm_). It is shown once."
ask_secret NPM_TOKEN "Paste the granular token (empty to skip):"
if [[ -n "$NPM_TOKEN" ]]; then
  set_secret NPM_TOKEN "$NPM_TOKEN"
else
  SKIPPED+=("NPM_TOKEN (generate one later under npmjs.com/settings/~/tokens)")
fi

# ── Verify ────────────────────────────────────────────────────────────────
if npm view "$PLACEHOLDER_NAME" version >/dev/null 2>&1; then
  printf '  %s✓ verified:%s %s@%s is live on the registry\n' \
    "$GREEN" "$RESET" "$PLACEHOLDER_NAME" "$(npm view "$PLACEHOLDER_NAME" version 2>/dev/null)"
else
  warn "Could not see ${PLACEHOLDER_NAME} on the registry yet; new packages can"
  warn "take a moment to index. Check https://npmjs.com/package/${PLACEHOLDER_NAME} later."
fi

finish
